'use strict';
const fs = require('node:fs');
const path = require('node:path');
const { EXTENSIONS, registrationEntries } = require('../src/windows-integration.cjs');
const executable = 'C:\\FRAMECUT_INSTALL_DIR\\Framecut.exe';
const nsis = value => value.replaceAll('$', '$$').replaceAll('"', '$\\"').replaceAll('C:\\FRAMECUT_INSTALL_DIR', '$INSTDIR');
const lines = [
  '; Generated by scripts/prepare-installer.cjs. Per-user registration; defaults remain user-controlled.',
  'LangString FramecutOpen 1033 "Open in Framecut"',
  'LangString FramecutOpen 1049 "Открыть в Framecut"',
  'LangString FramecutOpen 1031 "In Framecut öffnen"',
  'LangString FramecutOpen 3082 "Abrir en Framecut"',
  '!macro customInstall'
];
for (const [key, name, value] of registrationEntries(executable)) lines.push(`  WriteRegStr HKCU "${key.slice(5)}" "${nsis(name)}" "${nsis(value)}"`);
lines.push('  ClearErrors', '  ReadRegDWORD $0 HKCU "Software\\Framecut" "ContextMenuEnabled"', '  ${If} ${Errors}', '    StrCpy $0 1', '    WriteRegDWORD HKCU "Software\\Framecut" "ContextMenuEnabled" 1', '  ${EndIf}', '  ${If} $0 == 1');
for (const extension of EXTENSIONS) {
  const key = `Software\\Classes\\SystemFileAssociations\\.${extension}\\shell\\Framecut`;
  lines.push(`    WriteRegStr HKCU "${key}" "" "$(FramecutOpen)"`,
    `    WriteRegStr HKCU "${key}" "Icon" "$\\"$INSTDIR\\Framecut.exe$\\",0"`,
    `    WriteRegStr HKCU "${key}\\command" "" "$\\"$INSTDIR\\Framecut.exe$\\" $\\"%1$\\""`);
}
lines.push('  ${EndIf}', "  System::Call 'shell32::SHChangeNotify(i 0x08000000, i 0, p 0, p 0)'", '!macroend', '!macro customUnInstall');
for (const extension of EXTENSIONS) lines.push(`  DeleteRegKey HKCU "Software\\Classes\\SystemFileAssociations\\.${extension}\\shell\\Framecut"`, `  DeleteRegValue HKCU "Software\\Classes\\.${extension}\\OpenWithProgids" "Framecut.Video"`);
lines.push('  DeleteRegKey HKCU "Software\\Classes\\Framecut.Video"', '  DeleteRegKey HKCU "Software\\Classes\\Applications\\Framecut.exe"', '  DeleteRegKey HKCU "Software\\Framecut"', '  DeleteRegValue HKCU "Software\\RegisteredApplications" "Framecut"', "  System::Call 'shell32::SHChangeNotify(i 0x08000000, i 0, p 0, p 0)'", '!macroend', '');
fs.writeFileSync(path.join(__dirname, '..', 'assets', 'installer.nsh'), lines.join('\n'));
console.log('Prepared Windows application and context-menu registration.');
